  const o=K.orcs;const dl=o.darklord?C(S,o.darklord):null;const bes=S.settlements.filter(s=>s.status==='besieged'&&isFree(s.faction));const cand=S.dlCandidate?C(S,S.dlCandidate):null;let w='';
