if(watching){html+=meanwhile(h);html+=`<div class="group">${esc(h.name)}'s story</div>`+h.story.slice(-6).reverse().map(e=>`<div class="sumline"><span class="yr">Year ${e.year}</span>${esc(e.text)}</div>`).join('');return html+`</div>`;}
