  {const left=sw.will-spent;if(left>=3&&S.turn>0)html+=`<div class="willnote">${left} of ${sw.will} will unspent. A sword that wants nothing changes nothing; big desires win ages.</div>`;}
  const hist=sw.history.slice(-3).reverse();if(hist.length)html+=`<div class="group">The blade's road</div>`+hist.map(e=>`<div class="sumline"><span class="yr">Year ${e.year}</span>${esc(e.name)} — ${esc(e.text)}</div>`).join('');
