function showChapter(act){$('chapterArt').innerHTML=chapterSVG(act);$('chapterAct').textContent=`Act ${['','I','II','III','IV'][act]} · Year ${S.year}`;$('chapterTitle').textContent=ACT_NAMES[act];$('chapterLines').innerHTML=seerLines(act).map(t=>`<div>${esc(t)}</div>`).join('');$('chapter').classList.remove('hidden');}
function settlementSVG(s){const f=FACTIONS[s.faction];const col=f?f.color:'#888';const t=S.terrain[idx(s.x,s.y)];const sky=s.status==='sealed'?'#1a0a24':'#0e0a20';const big=s.type==='capital'||s.type==='fortress';const mid=s.type==='town'||s.type==='hold'||s.type==='haven'||s.type==='rhaven'||s.type==='dcamp';const n=big?9:mid?6:4;const seedv=s.id*13;
  let g=`<svg viewBox="0 0 320 110" class="townart" preserveAspectRatio="none"><defs><linearGradient id="tsk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${sky}"/><stop offset="1" stop-color="#2a1f4a"/></linearGradient></defs><rect width="320" height="110" fill="url(#tsk)"/>`;
  for(let k=0;k<18;k++){g+=`<circle cx="${(hashN(k+seedv,61)*320)|0}" cy="${(hashN(k+seedv,67)*50)|0}" r="0.8" fill="#fff" opacity="${0.3+hashN(k,71)*0.5}"/>`;}g+=`<circle cx="270" cy="22" r="10" fill="#f4e2a6" opacity=".9"/><circle cx="265" cy="19" r="8.5" fill="${sky}"/>`;
  const ground=t===TR.MOUNTAIN?'#4a4e58':t===TR.FOREST||t===TR.WOODS?'#173a2a':t===TR.GRAVE||t===TR.BARRENS?'#3a2f36':t===TR.HILLS?'#5f6d3c':'#6a6a3a';
  if(t===TR.MOUNTAIN)g+=`<path d="M0 90 L50 30 L100 70 L160 20 L220 66 L270 34 L320 90 Z" fill="#5e6470"/>`;
  if(t===TR.FOREST||t===TR.WOODS)for(let k=0;k<12;k++){const tx=k*28+hashN(k+seedv,73)*8;g+=`<path d="M${tx} 88 L${tx+10} ${50+hashN(k,79)*18} L${tx+20} 88 Z" fill="#1f5a3a"/>`;}
  g+=`<rect x="0" y="86" width="320" height="24" fill="${ground}"/>`;
  const race=s.race;const fallen=s.status==='fallen';const ruin=s.status==='ruined'||s.status==='sundered'||s.status==='sealed';
  if(s.status==='sealed'){g+=`<path d="M120 88 L120 46 Q160 26 200 46 L200 88 Z" fill="#2a2030" stroke="#a862d8" stroke-width="2"/><path d="M140 88 L140 60 Q160 48 180 60 L180 88 Z" fill="#0a0410"/><path d="M150 70 L170 70 M160 62 L160 78" stroke="#a862d8" stroke-width="2"/>`;}
  else if(s.status==='sundered'){g+=`<rect x="0" y="40" width="320" height="70" fill="#9aa6b8" opacity=".55"/><path d="M130 86 L130 50 L150 42 L170 50 L170 86" fill="none" stroke="#c8ccd8" stroke-width="1.5" opacity=".7"/>`;}
  else if(race==='dwarf'){g+=`<path d="M60 88 L60 40 Q160 4 260 40 L260 88 Z" fill="#5e6470"/><path d="M125 88 L125 56 Q160 34 195 56 L195 88 Z" fill="${fallen?'#3a1a1a':'#2a2530'}" stroke="${col}" stroke-width="2"/><path d="M145 88 L145 66 Q160 56 175 66 L175 88 Z" fill="#0e0a20"/>`;for(let k=0;k<n;k++){const wx=70+k*22;g+=`<rect x="${wx}" y="${58+hashN(k+seedv,83)*10}" width="5" height="4" fill="${fallen?'#e0563f':'#f4d56a'}" opacity=".9"/>`;}}
  else if(race==='highelf'||race==='woodelf'){for(let k=0;k<n;k++){const tx=40+k*(240/n)+hashN(k+seedv,89)*8;const th=big?38+hashN(k,97)*30:22+hashN(k,97)*16;g+=`<rect x="${tx}" y="${88-th}" width="7" height="${th}" fill="${fallen?'#3a2a2a':'#c9d4de'}" opacity=".95"/><path d="M${tx-3} ${88-th} L${tx+3.5} ${78-th} L${tx+10} ${88-th} Z" fill="${col}"/><rect x="${tx+2}" y="${94-th}" width="3" height="4" fill="${fallen?'#e0563f':'#f4e26a'}"/>`;}if(S.river[idx(s.x,s.y)])g+=`<path d="M0 100 C80 94 160 106 320 98 L320 110 L0 110 Z" fill="#3b86bd" opacity=".8"/><path d="M130 100 L170 100 L164 106 L136 106 Z" fill="#3a2a1a"/><rect x="149" y="84" width="2" height="16" fill="#3a2a1a"/><path d="M151 86 L165 96 L151 96 Z" fill="#e6dcc0"/>`;}
  else if(race==='orc'||race==='goblin'){if(s.type==='fortress'){g+=`<path d="M100 88 L100 44 L118 44 L118 36 L130 36 L130 44 L190 44 L190 36 L202 36 L202 44 L220 44 L220 88 Z" fill="#0a0408" stroke="#3a1a22" stroke-width="1"/><rect x="150" y="66" width="20" height="22" fill="#000"/><circle cx="155" cy="56" r="1.6" fill="#e0563f"/><circle cx="165" cy="56" r="1.6" fill="#e0563f"/>`;}for(let k=0;k<n;k++){const tx=30+k*(260/n);g+=`<path d="M${tx} 88 L${tx+10} 68 L${tx+20} 88 Z" fill="${'#4a2a2a'}"/><rect x="${tx+22}" y="62" width="1.5" height="26" fill="#8a8090"/><circle cx="${tx+22.7}" cy="61" r="2.5" fill="#e8e0d0"/>`;}g+=`<circle cx="160" cy="98" r="4" fill="#e08a3f"/><circle cx="160" cy="96" r="2" fill="#f4e26a"/>`;}
  else{const wood=s.faction==='vale';if(big||mid)g+=`<rect x="${big?60:90}" y="${big?56:66}" width="${big?200:140}" height="32" fill="${fallen?'#3a1a1a':wood?'#4a3520':'#2a2530'}" stroke="${col}" stroke-width="1.5"/>`;for(let k=0;k<(big?10:mid?6:0);k++)g+=`<rect x="${(big?62:92)+k*20}" y="${big?50:60}" width="8" height="8" fill="${fallen?'#3a1a1a':wood?'#4a3520':'#2a2530'}" stroke="${col}" stroke-width="1"/>`;for(let k=0;k<n;k++){const hx=40+k*(240/n)+hashN(k+seedv,101)*6;const hh=14+hashN(k+seedv,103)*12;g+=`<rect x="${hx}" y="${88-hh}" width="16" height="${hh}" fill="${fallen?'#2a1a1a':'#5a4a3a'}"/><path d="M${hx-2} ${88-hh} L${hx+8} ${80-hh} L${hx+18} ${88-hh} Z" fill="${wood?'#8a6a30':'#7a3a2a'}"/><rect x="${hx+6}" y="${94-hh}" width="4" height="4" fill="${fallen?'#e0563f':'#f4d56a'}"/>`;}if(big){g+=`<rect x="146" y="26" width="28" height="62" fill="${fallen?'#3a1a1a':'#2a2530'}" stroke="${col}" stroke-width="1.5"/><path d="M146 26 L160 12 L174 26 Z" fill="${col}"/>`;if(s.faction==='city'&&S.kingdoms.city.omen.val>50)g+=`<rect x="200" y="40" width="6" height="48" fill="#3a3a44"/><path d="M203 40 q6 -10 2 -20 q8 -6 3 -14" stroke="#8a8a9a" stroke-width="3" fill="none" opacity=".6"/>`;}}
  if(s.status==='besieged'){for(let k=0;k<4;k++){const fx=8+k*84+(k>1?60:0);g+=`<path d="M${fx} 96 L${fx+10} 80 L${fx+20} 96 Z" fill="#5a2a2a"/><circle cx="${fx+28}" cy="94" r="3" fill="#e0563f"/>`;}}
  if(fallen)g+=`<rect x="150" y="22" width="2" height="30" fill="#8a8090"/><path d="M152 22 L168 28 L152 34 Z" fill="#d9432c"/><path d="M40 60 q30 -20 60 -6" stroke="#8a8a9a" stroke-width="4" fill="none" opacity=".5"/>`;
  if(s.status==='ruined')g+=`<path d="M100 88 L110 70 L124 88 M170 88 L176 66 L192 88 L204 78 L214 88" fill="none" stroke="#3a3040" stroke-width="6"/>`;
  return g+`</svg>`;}
function nearThreats(x,y,faction,r){const out=[];for(const p of S.parties){if(!hostile(S,p.faction,faction)||!combatKind(p))continue;const d=mdist(p.x,p.y,x,y);if(d<=r)out.push([d,p]);}out.sort((a,b)=>a[0]-b[0]);return out;}
function partyLine(p){return`${esc(cap(p.name))} (${KIND_LABEL[p.kind]||p.kind}, strength ${Math.round(partyStrength(S,p))}), ${esc(goalText(p))}`;}
function renderSummary(){const K=S.kingdoms;const sw=S.sword;const st=sw.stats;const h=sw.holder?C(S,sw.holder):null;const act=actOfUI();const R=['','I','II','III','IV'];let html='';
  const sec=t=>`<div class="group">${t}</div>`;const line=(t,cls)=>`<div class="sumline${cls?' '+cls:''}">${t}</div>`;const B=t=>`<b>${t}</b> `;
  html+=`<div class="sumhead"><b>Year ${S.year}</b> · Act ${R[act]}, ${esc(ACT_NAMES[act])}${S.ended?' · the age has ended':S.turn===0?' · the age begins':''}</div>`;
  const pri={doom:0,hero:1,sword:2,quest:2.5,battle:3,march:4,realm:5,land:5.5,omen:6,life:7};const ev=S.chronicle.filter(e=>e.turn===S.turn&&S.turn>0).sort((a,b)=>pri[a.kind]-pri[b.kind]).slice(0,4);
  if(ev.length){html+=sec('This decade');for(const e of ev)html+=line(`<span class="yr" ${e.x!=null?`data-tile="${e.x},${e.y}" title="Go there"`:''}>${e.kind}</span>${esc(e.text.length>200?e.text.slice(0,198)+'…':e.text)}`,'k-'+e.kind);}
  html+=sec('The sword');
  if(h){const p=h.party?party(S,h.party):null;const foul=!isFree(h.faction);html+=line(B('Bearer:')+`${charLink(h)}, ${esc(RACE_NAMES[h.race])} ${esc(roleName(h))} of ${esc(FACTIONS[h.faction].short)}${h.sick?' <span class="warn">(sick)</span>':''}.`,foul?'danger':'');html+=line(B('Where:')+`${tileLink(h.x,h.y,whereIs(h))}${p?', '+esc(goalText(p))+' with '+esc(p.name):', staying put'}.`);
    if(foul)html+=line(`<span class="danger">In foul hands.</span> Only a hero who breaks ${esc(pn(h).p)} line can strike it free.`);
    const th=nearThreats(h.x,h.y,h.faction,6);html+=line(B('Danger:')+(th.length?`${esc(cap(th[0][1].name))} (strength ${Math.round(partyStrength(S,th[0][1]))}) is ${th[0][0]===0?'here':th[0][0]+' tile'+(th[0][0]>1?'s':'')+' away'}${p?', against our '+Math.round(partyStrength(S,p)):''}.`:'nothing hostile within six tiles.'),th.length?'warn':'');
    const dl=K.orcs.darklord?C(S,K.orcs.darklord):null;if(dl&&dl.alive&&!K.orcs.broken)html+=line(B('The Dark Lord:')+`${mdist(dl.x,dl.y,h.x,h.y)} tiles away.`);}
  else html+=line(B('Unclaimed.')+`Lying at ${tileLink(sw.x,sw.y,placeName(S,sw.x,sw.y))}${sw.lostTurns>1?' these '+sw.lostTurns*10+' years':''}.`,'warn');
  const spent=STAT_ORDER.reduce((t,k)=>t+st[k],0);const wants=STAT_ORDER.filter(k=>st[k]>0).map(k=>`${STAT_INFO[k][0]} ${st[k]}`).join(', ');const seekSel=$('seekSel');const seekLabel=seekSel&&seekSel.selectedIndex>=0?seekSel.options[seekSel.selectedIndex].textContent:sw.seek;
  html+=line(B('Will:')+`${spent} of ${sw.will} spent${wants?' — '+wants:''}. Seeks ${esc(seekLabel)}. Renown ${sw.renown}; ${sw.history.length} bearer${sw.history.length===1?'':'s'} so far.`);
  html+=sec(S.hard?'The champions':'The heroes');
  for(const k of['dwarves','elves','city']){const c=C(S,K[k].hero);if(!c)continue;const p=c.alive&&c.party?party(S,c.party):null;const q=c.quest?S.quests.find(x=>x.id===c.quest&&x.status==='active'):null;const ds=mdist(c.x,c.y,sw.x,sw.y);
    html+=line(`★ ${charLink(c)} (${esc(FACTIONS[k].short)}) — ${c.alive?`${tileLink(c.x,c.y,whereIs(c))}. ${q?`<b>Quest:</b> ${esc(q.title)} — ${questObjective(q)}.`:p&&p.goal?`<b>Doing:</b> ${esc(goalText(p))}.`:'<b>Doing:</b> nothing in particular.'} ${c.id===sw.holder?'<b>Bears the sword.</b>':ds===0?'With the sword.':`${ds} tiles from the sword.`}${c.sick?' <span class="warn">Sick.</span>':''}`:`dead: ${esc(c.deathCause)}.`}`);}
  html+=sec('The South');
  const o=K.orcs;if(o.broken)html+=line(B('The Host is broken.')+'The tribes are back to raiding and quarrelling.');
  else if(o.risen){const dl=C(S,o.darklord);const f=setById(S,o.fortress);const dp=dl.party?party(S,dl.party):null;html+=line(B('The Dark Lord:')+`${charLink(dl)} ${esc(dl.title)}, ${dp?`riding with ${esc(dp.name)}, ${esc(goalText(dp))}`:`behind the walls of ${tileLink(f.x,f.y,f.name)}`}${f.status==='ruined'?' (his fortress is a ruin)':''}.${dl.id===sw.holder?' <b class="danger">He holds the sword.</b>':''}`,'danger');
    const armies=S.parties.filter(p=>p.faction==='orcs'&&p.kind==='army');html+=line(B('Hordes in the field:')+(armies.length?armies.map(a=>`${esc(a.name)} (${Math.round(partyStrength(S,a))}) ${esc(goalText(a))}`).join('; ')+'.':'none this decade.'));}
  else{const cand=S.dlCandidate?C(S,S.dlCandidate):null;html+=line(B('No Dark Lord yet.')+(S.turn<30?'The tribes raid the borders and quarrel among the swamp barrows.':'The tribes are gathering; something is coming.'));if(cand&&cand.alive)html+=line(B('The Dreamer:')+`${charLink(cand)} gathers the tribes at ${tileLink(cand.x,cand.y,whereIs(cand))}. Kill ${esc(pn(cand).o)} before ${esc(pn(cand).s)} is crowned and the rising comes later and weaker.`,'warn');
    const wb=S.parties.filter(p=>p.faction==='orcs'&&p.kind==='warband'&&p.goal&&p.goal.type==='settlement');if(wb.length)html+=line(B('Raiders:')+wb.slice(0,3).map(w=>`${esc(w.name)} ${esc(goalText(w))}`).join('; ')+'.');}
  const bes=S.settlements.filter(s=>s.status==='besieged'&&isFree(s.faction));html+=line(B('Sieges:')+(bes.length?bes.map(s=>`${tileLink(s.x,s.y,s.name)} (walls ${s.walls}, garrison ${s.garrison})`).join('; ')+'.':'none.'),bes.length?'warn':'');
  const gob=S.parties.filter(p=>p.faction==='goblins');if(gob.length)html+=line(B('Goblins:')+`${gob.length} band${gob.length>1?'s':''} loose under the mountain${S.chars.some(c=>c.alive&&c.role==='goblinking')?', with a king among them':''}.`);
  html+=sec('The crowns');
  for(const k of['dwarves','elves','vale','city']){const kk=K[k];const cs=kk.capital?setById(S,kk.capital):null;const l=kk.leader?C(S,kk.leader):null;let stw=kk.status;if(k==='city'&&kk.vassal)stw='vassal';const stWord={standing:'',fallen:'capital lost',sealed:'sealed in the Deeps',sundered:'gone into the mist',vassal:'bent the knee to the South'}[stw]||stw;
    let t=`<b style="color:${FACTIONS[k].color}">${esc(FACTIONS[k].short)}</b>${stWord?' — <span class="warn">'+esc(stWord)+'</span>':''}. `;t+=l&&l.alive?`${esc(kk.leaderTitle)} ${charLink(l)}`:'No one on the seat';t+=cs?` at ${tileLink(cs.x,cs.y,cs.name)} (${esc(statusWord(cs))}, garrison ${cs.garrison}).`:'.';
    if(OWNID[k]&&kk.status==='standing'){const dv=devCount(S,kk);t+=` Land: ${dv} of ${kk.need} ${devWord(k,true)} needed${kk.wants==='forest'?' — <span class="warn">out of timber</span>':kk.hunger>=2?' — <span class="warn">short of land</span>':''}.`;t+=kk.mistake?' <span style="color:#b04ad8">Its mistake is made.</span>':` ${esc(kk.omen.label)}: <span style="color:${omenColor(kk.omen.val)}">${Math.round(kk.omen.val)}</span> of 100.`;}
    html+=line(t);}
  const pairs=[['dwarves','elves'],['dwarves','city'],['elves','city']];html+=line(B('Between the crowns:')+pairs.map(([a,b])=>`${esc(FACTIONS[a].short)}–${esc(FACTIONS[b].short)} ${atWar(S,a,b)?'<span class="danger">at war</span>':relWord(rel(S,a,b))}`).join(' · ')+(S.alliance?' · <span style="color:#9fbf6a">the Oath of the Council holds</span>':'')+'.');
  const road=S.parties.filter(p=>p.kind==='envoy'||p.kind==='settlers'||(p.kind==='host'&&p.expedition));if(road.length)html+=line(B('On the road:')+road.map(p=>`${esc(p.name)} (${KIND_LABEL[p.kind]||p.kind}) ${esc(goalText(p))}`).join('; ')+'.');
  const active=S.quests.filter(q=>q.status==='active'&&q.kind!=='epilogue').sort((a,b)=>(b.main?1:0)-(a.main?1:0));html+=sec(`Quests under way (${active.length})`);
  if(!active.length)html+=line('Nothing is asked of anyone right now.');for(const q of active)html+=line(`<span class="qb">${q.main?'main':'side'}</span><b>${esc(q.title)}</b>${questObjective(q)?' — '+questObjective(q):''}${questWho(q)?' ('+questWho(q)+')':''}.`);
  return html;}
function questWho(q){const K=S.kingdoms;const hs=(q.heroes||[]).map(id=>C(S,id)).filter(Boolean);if(hs.length)return hs.map(h=>charLink(h)).join(', ');if(q.kind==='envoy'||q.kind==='expedition'){const p=party(S,q.party);const l=q.lead?C(S,q.lead):(p?C(S,p.members[0]):null);return (l?charLink(l)+', ':'')+esc(FACTIONS[q.from].short);}if(q.kind==='develop')return esc(FACTIONS[q.faction].short);if(q.kind==='council')return q.arrived.length?q.arrived.map(k=>FACTIONS[k].short).join(', ')+' at the table':'envoys on the road';if(q.kind==='siege')return 'every host that can be spared';return '';}
function questObjective(q){switch(q.kind){case 'develop':return`${S.kingdoms[q.faction].dev} of ${q.target} ${devWord(q.faction,true)}`;case 'hunt':{const c=q.targetChar?C(S,q.targetChar):null;const p=q.targetParty?party(S,q.targetParty):null;return c?`hunt ${charLink(c)}`:p?`destroy ${esc(p.name)}`:'';}case 'scout':return q.stage==='out'?`ride to ${tileLink(q.x,q.y,placeName(S,q.x,q.y))}`:'bring word home';case 'envoy':return`ask for the land around ${tileLink(q.x,q.y,clusterNameUI(q))}`;case 'expedition':return`seize the land around ${tileLink(q.x,q.y,clusterNameUI(q))}`;case 'defend':case 'siege':{const s=setById(S,q.settlement);return`${q.kind==='defend'?'hold':'take'} ${tileLink(s.x,s.y,s.name)}`;}case 'council':return`${q.arrived.length} of ${q.expected.length} crowns present`;case 'recover':return`find ${esc(S.sword.name)}`;case 'foulhands':return`take back ${esc(S.sword.name)}`;case 'strike':return 'kill the Dark Lord in the field';default:return'';}}
function clusterNameUI(q){const i=q.tiles[Math.floor(q.tiles.length/2)];return placeName(S,i%W,(i/W)|0);}
function renderQuests(main){const acts={};for(const q of S.quests){if(!!q.main!==!!main)continue;(acts[q.act]||(acts[q.act]=[])).push(q);}const cur=S.quests.filter(q=>q.status==='active'&&!!q.main===!!main);
  const act=actOfUI();let html=main?goalsHTML()+`<div class="acts">${[1,2,3,4].map(a=>`<span class="${a<act?'past':a===act?'cur':''}"><b>${['','I','II','III','IV'][a]}</b>${esc(ACT_NAMES[a])}</span>`).join('')}</div>`:'';html+=`<div class="hint" style="margin-bottom:8px">${cur.length?`${cur.length} ${main?'main':'side'} quest${cur.length>1?'s':''} under way in Act ${['','I','II','III','IV'][act]}, ${esc(ACT_NAMES[act])}.`:main?'No main quest is open right now. The age is between chapters.':'No side quests are open right now.'}</div>`;
  for(const a of[4,3,2,1]){const list=acts[a];if(!list)continue;html+=`<div class="group">Act ${['','I','II','III','IV'][a]} — ${esc(ACT_NAMES[a])}</div>`;
    for(const q of list.slice().reverse()){const st=q.status;const mark=st==='done'?'✓':st==='failed'?'✗':'…';const open=openQuest===q.id;html+=`<div class="quest q-${st}${open?' open':''}${q.main?' q-main':' q-side'}" data-q="${q.id}"><div class="qh" title="Open"><span class="qm">${mark}</span><span class="qt">${esc(q.title)}</span><span class="qb">${q.main?'main':'side'}</span><span class="qy">${q.start*10}${q.end!=null&&q.end!==q.start?'–'+q.end*10:''}</span></div><p>${esc(q.text)}</p>${st==='active'?`<div class="qo">${questObjective(q)}${questWho(q)?' — '+questWho(q):''}</div>`:`<div class="qo ${st}">${esc(q.outcome||'')}</div>`}${open?questHistory(q):''}</div>`;}}
  return html;}
function questHistory(q){const ids=new Set([...(q.chars||[]),...(q.heroes||[])]);const endT=q.end==null?S.turn:q.end;const list=S.chronicle.filter(e=>e.turn>=q.start&&e.turn<=endT&&(e.text.includes(q.title)||e.chars.some(id=>ids.has(id)))).slice(-14);
  let html=`<div class="qdet"><div class="qmeta">${q.kind==='envoy'||q.kind==='expedition'?'Asked by '+esc(FACTIONS[q.from].short)+' of '+esc(FACTIONS[q.to].short):q.faction?'Asked of '+esc(FACTIONS[q.faction].short):'Asked of the heroes'}${questWho(q)?' · '+questWho(q):''} · ${tileLink(q.x,q.y,'where it began')}</div>`;
  if(!list.length)html+=`<div class="hint">The chronicle has nothing more to say about it.</div>`;for(const e of list)html+=`<div class="entry k-${e.kind}"><span class="yr" ${e.x!=null?`data-tile="${e.x},${e.y}"`:''}>Year ${e.year}</span>${esc(e.text)}</div>`;return html+`</div>`;}
function actOfUI(){const r=S.kingdoms.orcs.riseTurn;if(!r)return S.turn<26?1:2;return S.turn<r+25?3:4;}
function renderTile(){if(!sel.tile)return`<div class="hint">Click a tile on the map to see what is there.</div>`;const[x,y]=sel.tile;const i=idx(x,y);const s=settlementAt(S,x,y);const sw=S.sword;
  const own=S.owner?S.owner[i]:0;let html=`<div class="sheet"><div class="title">${esc(s?s.name:cap(placeName(S,x,y)))}</div><div class="sub">${esc(TINFO[S.terrain[i]].name)}${S.river[i]?', on the river':''}, in the ${REGION_NAMES[S.region[i]]}${own?`. Land of ${esc(FACTIONS[OWN[own]].short)}`:'. No crown claims it'}${S.dev&&S.dev[i]&&own?`, ${esc(devWord(OWN[own],false))} here`:''}</div>`;
  if(s)html+=settlementSVG(s);else html+=sceneSVG({x,y,faction:'vale',race:'human',party:null,quest:null,id:0},{figure:false});
  if(s){html+=`<dl><dt>Settlement</dt><dd>${esc(typeWord(s))} of ${esc(FACTIONS[s.faction].short)}</dd><dt>Status</dt><dd>${esc(statusWord(s))}${s.fallTurn?', since year '+s.fallTurn*10:''}</dd><dt>People</dt><dd>about ${s.pop.toLocaleString()}</dd><dt>Prosperity</dt><dd>${Math.round(s.prosperity)}</dd><dt>Defence</dt><dd>walls ${s.walls}, garrison ${s.garrison}${s.orcGarrison?', orc garrison '+s.orcGarrison:''}</dd></dl>`;}
  if(!sw.holder&&sw.x===x&&sw.y===y)html+=`<div class="card"><div class="nm">${esc(sw.name)} lies here</div><p>Unclaimed. Anyone who passes may take it up.</p></div>`;
  const here=charsAt(S,x,y);if(!here.length)html+=`<div class="hint">No named souls are here.</div>`;
  const groups=new Map();for(const c of here){const k=c.party||0;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(c);}
  for(const[k,list]of groups){const p=k?party(S,k):null;html+=`<div class="group">${p?esc(cap(p.name))+' — '+(KIND_LABEL[p.kind]||p.kind)+(p.might?', strength '+Math.round(partyStrength(S,p)):'')+', '+esc(goalText(p)):(s?'Living in '+esc(s.name):'Here')}</div>`;for(const c of list)html+=personRow(c);}
  return html+`</div>`;}
function personRow(c){return`<div class="person" data-char="${c.id}"><i class="dot" style="background:${colorFor(c)}"></i>${c.hero?'★ ':''}${c.role==='leader'?'♛ ':''}${c.id===S.sword.holder?'† ':''}${esc(c.name)} <span class="role">${esc(roleName(c))}, ${ageText(c)}${c.sick?', sick':''}</span></div>`;}
function renderSoul(){if(!sel.char)return`<div class="hint">Click one of the tiny markers on the map, or a name anywhere, to read a soul.</div>`;const c=C(S,sel.char);const sw=S.sword;const home=c.home?setById(S,c.home):null,born=c.birthplace?setById(S,c.birthplace):null;const p=c.party?party(S,c.party):null;const held=sw.history.filter(e=>e.holder===c.id).length;
  let html=`<div class="sheet"><div class="title">${esc(c.name)}${c.title?' '+esc(c.title):''}</div><div class="sub">${esc(RACE_NAMES[c.race])} ${esc(roleName(c))} of ${esc(FACTIONS[c.faction].short)}${c.alive?'':c.departed?', gone beyond the mist':', dead'}</div><dl>`;
  html+=`<dt>Age</dt><dd>${ageText(c)}</dd><dt>Born</dt><dd>year ${c.born}${born?', in '+esc(born.name):''}${c.parent?', child of '+esc(c.parent):''}</dd><dt>Home</dt><dd>${home?tileLink(home.x,home.y,home.name):'none'}</dd>`;
  if(c.alive)html+=`<dt>Now</dt><dd>at ${tileLink(c.x,c.y,whereIs(c))}${p?', with '+esc(p.name)+', '+esc(goalText(p)):''}</dd>`;else html+=`<dt>Died</dt><dd>year ${c.deathYear}: ${esc(c.deathCause)}</dd>`;
  html+=`<dt>Strength</dt><dd>${c.strength}${c.renown?', renown '+c.renown:''}${c.kills?', '+c.kills+' foes felled':''}</dd>`;
  if(c.sick)html+=`<dt>Health</dt><dd>sick with the fever</dd>`;
  html+=`<dt>The sword</dt><dd>${c.id===sw.holder?'bears '+esc(sw.name)+' now':held?'held '+esc(sw.name)+' '+held+' time'+(held===1?'':'s'):'never held it'}</dd></dl>`;
  for(const[k,l]of[['valor','Valor'],['prudence','Prudence'],['ambition','Ambition'],['wanderlust','Wanderlust'],['loyalty','Loyalty']])html+=`<div class="trait"><span>${l}</span><div class="bar"><i style="width:${c.traits[k]*11}%;background:${colorFor(c)}"></i></div></div>`;
  html+=`<p>Likes ${esc(c.like)}. Fears ${esc(c.fear)}. Wants ${esc(wantText(S,c))}.</p><div class="storylog">`;
  for(let i=c.story.length-1;i>=0;i--)html+=`<div><span class="yr">Year ${c.story[i].year}</span>${esc(c.story[i].text)}</div>`;
  return html+`</div></div>`;}
function renderHeroes(){const K=S.kingdoms;let html='';const card=(c,who)=>{if(!c)return'';const p=c.alive&&c.party?party(S,c.party):null;return`<div class="card"><div class="nm">${c.hero?'★ ':''}${esc(c.name)} ${esc(c.title||'')}</div><div class="who">${esc(who)}</div><p>${c.alive?`At ${tileLink(c.x,c.y,whereIs(c))}${p?', with '+esc(p.name)+', '+esc(goalText(p)):''}. Age ${ageText(c)}. Renown ${c.renown}${c.id===S.sword.holder?'. <b>Bears '+esc(S.sword.name)+'.</b>':''}${c.quest&&S.quests.find(q=>q.id===c.quest&&q.status==='active')?' Quest: <i>'+esc(S.quests.find(q=>q.id===c.quest).title)+'</i>.':''}`:`Dead: ${esc(c.deathCause)}.`} ${charLink(c)}</p></div>`;};
  html+=`<div class="group">${S.hard?'Champions — ordinary folk, no prophecy':'The marked'}</div>`;for(const k of['dwarves','elves','city']){const hc=C(S,K[k].hero);if(hc)html+=card(hc,`${RACE_NAMES[hc.race]} ${S.hard?'champion':'hero'}, ${FACTIONS[k].short}`);}
  if(K.orcs.darklord){html+=`<div class="group">The South</div>`;html+=card(C(S,K.orcs.darklord),'the Dark Lord');}
  html+=`<div class="group">Crowns</div>`;for(const k of['dwarves','elves','vale','city']){const kk=K[k];if(kk.leader)html+=card(C(S,kk.leader),`${kk.leaderTitle}, ${FACTIONS[k].short}`);else html+=`<div class="card"><div class="nm">${esc(FACTIONS[k].short)}</div><p>${kk.status==='sealed'?'No crown. The halls are sealed.':kk.status==='sundered'?'No crown. The court went into the mist.':'The seat is empty.'}</p></div>`;}
  return html;}

/* ---------- the seer ---------- */
function fitBlock(b,will){const o=Object.assign({keen:0,ward:0,valor:0,glory:0,call:0,counsel:0},b);let sum=STAT_ORDER.reduce((t,k)=>t+o[k],0);while(sum>will){let mk=null,mv=-1;for(const k of STAT_ORDER)if(o[k]>mv){mv=o[k];mk=k;}o[mk]--;sum--;}return o;}
function blockText(b){return STAT_ORDER.filter(k=>b[k]>0).map(k=>`${STAT_INFO[k][0]} ${b[k]}`).join(', ')||'nothing';}
async function consultSeer(){if(seerBusy)return;stopPlay();const K=S.kingdoms;const sw=S.sword;const will=sw.will;const hn=k=>C(S,K[k].hero);
  const blocks=[{nm:`To ${hn('dwarves').name}, the dwarf hero`,seek:'dwarfhero',b:fitBlock({call:5,ward:2,keen:1},will),primary:'reach'},{nm:`To ${hn('elves').name}, the elf hero`,seek:'elfhero',b:fitBlock({call:5,ward:2,keen:1},will),primary:'reach'},{nm:`To ${hn('city').name}, the human hero`,seek:'humanhero',b:fitBlock({call:5,ward:2,keen:1},will),primary:'reach'},
    {nm:'Hold the line',seek:sw.seek,b:fitBlock({valor:3,keen:3,ward:2},will),primary:'holds'},{nm:'Retreat in glory',seek:sw.seek,b:fitBlock({glory:4,ward:2,counsel:2},will),primary:'survive'},{nm:'Counsel the crown',seek:sw.seek,b:fitBlock({counsel:5,glory:3},will),primary:'noMistake'},{nm:'Stay the course',seek:sw.seek,b:Object.assign({},sw.stats),primary:'holds'}];
  $('seer').classList.remove('hidden');$('seerLede').textContent='The Seer looks into the river and plays the next fifty years many times over.';const wrap=$('seerCards');wrap.innerHTML=blocks.map((bl,i)=>`<div class="seercard busy" id="sc${i}"><div class="nm">${esc(bl.nm)}</div><div class="blk">${esc(blockText(bl.b))}${bl.seek!==sw.seek||bl.primary==='reach'?', seeking '+esc(seekOptions().find(o=>o[0]===bl.seek)[1]):''}</div><div class="big">…<small>the Seer is looking</small></div></div>`).join('');
  seerBusy=true;$('btnSeer').disabled=true;const runs=8,turns=5;
  for(let i=0;i<blocks.length;i++){await new Promise(r=>setTimeout(r,30));const bl=blocks[i];let res;try{res=project(S,bl.b,bl.seek,turns,runs,i+1);}catch(err){console.error(err);res=null;}
    const el=$('sc'+i);if(!el)continue;el.classList.remove('busy');if(!res){el.querySelector('.big').innerHTML='?<small>the river was muddy</small>';continue;}
    const pct=k=>Math.round(100*res[k]/res.runs);const seek0=sw.seek;sw.seek=bl.seek;const t=seekTarget(S);sw.seek=seek0;
    const primary=bl.primary==='reach'?`${pct('reach')}%<small>the sword reaches ${esc(t?t.name:'them')} within fifty years</small>`:bl.primary==='holds'?`${pct('holds')}%<small>no free capital is lost in fifty years</small>`:bl.primary==='survive'?`${pct('survive')}%<small>the bearer lives and keeps the sword</small>`:`${pct('noMistake')}%<small>no kingdom makes its great mistake</small>`;
    const odds=`<div class="odds">Bearer lives and keeps it: <b>${pct('survive')}%</b><br>No free capital lost: <b>${pct('holds')}%</b><br>No great mistake: <b>${pct('noMistake')}%</b>${K.orcs.risen&&!K.orcs.broken?`<br>Dark Lord slain: <b>${pct('dlDead')}%</b>`:''}</div>`;
    el.innerHTML=`<div class="nm">${esc(bl.nm)}</div><div class="blk">${esc(blockText(bl.b))}${bl.seek!==sw.seek||bl.primary==='reach'?', seeking '+esc(seekOptions().find(o=>o[0]===bl.seek)[1]):''}</div><div class="big">${primary}</div>${odds}<button data-choose="${i}">Set the sword's will to this</button>`;
    el.querySelector('button').onclick=()=>{Object.assign(sw.stats,bl.b);sw.seek=bl.seek;renderSword();$('seer').classList.add('hidden');showToast(`The sword's will is set: ${blockText(bl.b)}.`);};}
  $('seerLede').textContent='Eight futures for each choice, fifty years deep. The river never shows the same thing twice.';seerBusy=false;$('btnSeer').disabled=false;}

/* ---------- fates ---------- */
function showFates(){const f=S.fates;if(!f)return;stopPlay();$('fateTitle').textContent=f.title;$('fateLede').textContent=`The ${S.ageName} is over. A thousand years have passed.`;$('fateText').textContent=f.text;
  $('fateCards').innerHTML=f.fates.map(x=>`<div class="card"><div class="nm">${esc(x.name)}</div><div class="who">${esc(x.who)}</div><p>${esc(x.text)} <span class="link" data-char="${x.id}">read</span></p></div>`).join('');
  $('fateSword').innerHTML=`<b style="font-family:var(--display);font-size:13px;letter-spacing:.06em;color:var(--gold)">${esc(S.sword.name)}</b><br>${esc(f.sword)}`;
  $('fateKingdoms').innerHTML=f.kingdoms.map(k=>`<div><b>${esc(cap(k.name))}</b><br>${esc(k.text)}</div>`).join('')+`<div><b>The deeds of the age</b><br>${f.questsDone} quests fulfilled, ${f.questsFailed} came to nothing.</div>`;
  $('chapter').classList.add('hidden');drawReplay();$('fates').classList.remove('hidden');}
function drawReplay(){const cv=$('replayCv');const g=cv.getContext('2d');const sc=cv.width/W;g.fillStyle='#0a0822';g.fillRect(0,0,cv.width,cv.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=S.terrain[idx(x,y)];g.fillStyle=TINFO[t].col;g.fillRect(x*sc,y*sc,sc+0.5,sc+0.5);if(S.river[idx(x,y)]&&t!==TR.OCEAN&&t!==TR.LAKE){g.fillStyle='#2f78b0';g.fillRect(x*sc+sc*0.3,y*sc+sc*0.3,sc*0.4,sc*0.4);}}
  const tr=S.swordTrail||[];g.strokeStyle='rgba(244,226,166,0.85)';g.lineWidth=2.2;g.lineJoin='round';g.beginPath();tr.forEach(([x,y],i)=>{const px=(x+0.5)*sc,py=(y+0.5)*sc;if(i===0)g.moveTo(px,py);else g.lineTo(px,py);});g.stroke();
  for(const s of S.settlements){if(s.type==='village'||s.type==='camp')continue;g.fillStyle=FACTIONS[s.faction].color;g.beginPath();g.arc((s.x+0.5)*sc,(s.y+0.5)*sc,sc*0.45,0,6.283);g.fill();}
  const pri={doom:0,hero:0.5,sword:1,quest:1.5};const cand=S.chronicle.filter(e=>e.x!=null&&(e.kind==='doom'||e.kind==='hero'||(e.kind==='sword'&&/changed|took up|struck|laid|lay/.test(e.text))||(e.kind==='quest'&&/fulfilled|failed/.test(e.text)&&S.quests.some(q=>q.main&&e.text.startsWith(q.title)))));
  const picked=[];const seenTurn=new Set();for(const e of cand.slice().sort((a,b)=>pri[a.kind]-pri[b.kind]||a.turn-b.turn)){if(picked.length>=10)break;if(seenTurn.has(e.turn))continue;seenTurn.add(e.turn);picked.push(e);}picked.sort((a,b)=>a.turn-b.turn);
  picked.forEach((e,i)=>{const px=(e.x+0.5)*sc,py=(e.y+0.5)*sc;g.beginPath();g.arc(px,py,sc*0.9,0,6.283);g.fillStyle=e.kind==='doom'?'#b04ad8':e.kind==='hero'?'#8fe0ff':'#f4e2a6';g.fill();g.strokeStyle='#0a0822';g.lineWidth=1.5;g.stroke();g.fillStyle='#0a0822';g.font=`bold ${Math.round(sc*1.1)}px Georgia,serif`;g.textAlign='center';g.textBaseline='middle';g.fillText(String(i+1),px,py+0.5);});
  $('replayList').innerHTML=picked.map((e,i)=>`<div><b>${i+1} · ${e.year}</b>${esc(e.text.length>150?e.text.slice(0,148)+'…':e.text)}</div>`).join('')||'<div class="hint">The sword\'s road left no marks on the map.</div>';}

/* ---------- boot ---------- */
function startGame(seed){startGameInner(seed);Music.start();Music.setMode('peace');let seen=false;try{seen=!!localStorage.getItem('sm_howto');}catch(e){}if(!seen){setTimeout(showHowto,400);}}
function startGameInner(seed){{const mode=$('modeSel')?$('modeSel').value:'normal';S=genWorld(seed,{hard:mode==='hard'});S.mode=mode;if(S.mode==='easy'){S.sword.will+=2;}}S.advisorName=['Ithariel','Serapheth','Anwen of the Seven Lamps','Cael the Watcher','Vesperine'][seed%5];watchId=null;lastAct=1;untilPress=false;terrainVer=-1;ISO.reset();sel={tile:null,char:null};hoverChar=null;tab='bearer';filter='all';anim={active:false,t0:0,dur:1200,prev:new Map()};stopPlay();$('intro').classList.add('hidden');$('fates').classList.add('hidden');resize();fitView();renderAll();
  const h=C(S,S.sword.holder);showToast(`${h.name} pulled ${S.sword.name} from the river. Its will is yours.`);}
function parseSeed(v){v=String(v||'').trim();if(!v)return(Math.random()*1e9)|0;if(/^\d+$/.test(v))return parseInt(v,10)|0;return hashStr(v)|0;}
function boot(){setupMap();resize();ISO.load();$('btnMapMode').onclick=()=>setMapMode(mapMode==='iso'?'classic':mapMode==='classic'?'fancy':'iso');$('howtoGo').onclick=()=>{$('howto').classList.add('hidden');const again=$('howtoAgain')&&$('howtoAgain').checked;try{if(again)localStorage.removeItem('sm_howto');else localStorage.setItem('sm_howto','1');}catch(e){}};$('btnSave').onclick=()=>saveGame();$('btnLoad').onclick=()=>loadGame();$('btnContinue').onclick=()=>loadGame();$('btnMute').onclick=()=>Music.setMuted(!Music.muted);$('btnMute').textContent=Music.muted?'🔇':'🔊';$('introHowto').onclick=()=>{try{localStorage.removeItem('sm_howto');}catch(e){}showToast('The guide will show when the next age begins.');};updateSaveButtons();$('chapterGo').onclick=()=>{$('chapter').classList.add('hidden');if(resumeAfterChapter&&S&&!S.ended){resumeAfterChapter=false;startPlay();}};$('seedInput').value=String((Math.random()*1e9)|0);$('btnBegin').onclick=()=>{const sd=parseSeed($('seedInput').value);let done=Tut_doneMem;try{done=done||!!localStorage.getItem('sm_tut_done');}catch(e){}if(!done)Tut.start(()=>startGame(sd));else startGame(sd);};$('btnTut').onclick=()=>{const sd=parseSeed($('seedInput').value);Tut.start(()=>startGame(sd));};$('seedInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('btnBegin').click();});
  $('btnStep').onclick=()=>{stopPlay();stepTurn();};$('btnPlay').onclick=()=>playing?stopPlay():startPlay();$('speed').onchange=()=>{if(playing){stopPlay();startPlay();}};
  $('btnSeer').onclick=consultSeer;$('seerClose').onclick=()=>$('seer').classList.add('hidden');$('fateClose').onclick=()=>$('fates').classList.add('hidden');$('fateNew').onclick=()=>{$('fates').classList.add('hidden');$('seedInput').value=String((Math.random()*1e9)|0);$('intro').classList.remove('hidden');};
  $('legend').innerHTML=`<span><i style="background:#e6a24a"></i>dwarves</span><span><i style="background:#8fe0ff"></i>high elves</span><span><i style="background:#86d66e"></i>wood elves</span><span><i style="background:#e9d38a"></i>humans</span><span><i style="background:#d9432c"></i>orcs</span><span><i style="background:#b56fe0"></i>goblins</span><span>◆ ✿ ≡ delving, grove, farm</span><span>⛵ ship</span><span>★ hero</span><span>♛ crown</span><span><i style="background:transparent;border-color:#f4e2a6;box-shadow:0 0 6px #d9b45a"></i>the sword</span>`;
  requestAnimationFrame(frame);}
document.addEventListener('DOMContentLoaded',boot);
